def solve():
    n = int(input())
    a = list(map(int, input().split()))

    for i in range(n):
        a[i] = [a[i], i]

    for bit in range(int(math.log2(n)) + 1):
        for i in range(1, 1 << bit):
            if a[i-1][0] > a[i][0]:
                a[i-1][0] -= 1 << bit
                a[i][0] -= 1 << bit

    sorted_a = sorted(a, key=lambda x: x[0])
    return all(x[0] == y[0] and x[1] <= y[1] for x, y in zip(a, sorted_a))

for _ in range(int(input())):
