                    for i in range(-1, 2):
                        if 0 <= pos + i < 4 and (pos + i, s[pos + i], count + 1) not in visited:
                            next_level.add((pos + i, s[pos + i], count + 1))
                if pos == 3 and s[pos]!= '0':
                    if (pos - 1, s[pos - 1], count + 1) not in visited:
                        next_level.add((pos - 1, s[pos - 1], count + 1))
                    if (pos + 1, s[pos + 1], count + 1) not in visited:
