def solve():
    n = int(input())
    a = list(map(int, input().split()))
    factors = defaultdict(list)
    max_val = 0
    for num in a:
        max_val = max(max_val, num)
        for p in range(2, int(math.sqrt(num)) + 1):
            if num % p == 0:
                factors[num].append(p)
                factors[num].append(num // p)
        if num > 1:
            factors[num].append(num)
    dp = [[0] * (max_val + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(max_val + 1):
            if a[i - 1] > j:
                dp[i][j] = dp[i - 1][j]
            elif dp[i - 1][j]:
                dp[i][j + a[i - 1]] = 1
                dp[i][j] = 1
                for p in factors[a[i - 1]]:
                    dp[i][j] |= not dp[i - 1][j]
    def f():
        ans1, ans2 = [], []
        j, i = max_val, n
        while i >= 0:
            if not dp[i][j]:
                ans2.append(a[i - 1])
                j -= a[i - 1]
                i -= 1
            else:
                ans1.append(a[i - 1])
                j -= a[i - 1]
                i -= 1
        return ans1, ans2[::-1]
    if not dp[n][0]:
        print(-1)
    else:
        a1, a2 = f()
