            while i < n:
                if a[i] == 0:
                    i += 1
                elif a[i] <= i:
                    result.append('NO')
                    break
                elif a[i] < i and not visited[a[i] - 1]:
                    visited[a[i] - 1] = 1
                    j = i - a[i]
                    while j > 0:
                        if a[j] <= j or a[j] < i or a[j] < j:
                            result.append('NO')
                            break
                        visited[a[j] - 1] = 1
                        j -= 1
                    i = i - a[i]
                else:
