import sys
from collections import deque

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        a = [0] + a
        result = [0] * (n + 1)
        for i in range(1, n + 1):
            temp = list(input().split())
            u_count, u = 0, ''
            for c in temp[1]:
                if c == 'U':
                    u_count += 1
                else:
                    u += c
            u = u[::-1]
            q = deque(u)
            for j in range(len(u)):
                if q[j] == 'D':
                    q[j] = str((int(q[j]) - u_count) % 10)
                elif q[j] == 'U':
                    q[j] = str((int(q[j]) + u_count) % 10)
            result[i] = str((a[i] - int(q[0]) + 10) % 10)
            for j in range(1, len(q)):
                a[i + j] = int(q[j])
        for i in range(1, n + 1):
            sys.stdout.write(str(result[i]) +'')
        sys.stdout.write('\n')

solve()
