from collections import Counter

def solve():
    s = input()
    counter = Counter()
    days = 0
    for char in s:
        if char not in counter:
            counter[char] += 1
            if len(counter) > 3:
                counter = Counter()
                counter[char] += 1
                days += 1
        else:
            counter[char] += 1
            if len(counter) > 3:
                counter = Counter({char: 1})
                days += 1
    print(days + 1)

test_cases = int(input())
for _ in range(test_cases):
    solve()
